INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (1, 'Reino Unido', 'United Kingdom', 'GB', 'europa', 'Alto', 'Inglês', 'Tradição, pontualidade e vida acadêmica centenária.', 'Universidades renomadas e forte cena cultural, de Londres a Manchester.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Flag_of_the_United_Kingdom_%281-2%29.svg/960px-Flag_of_the_United_Kingdom_%281-2%29.svg.png', 894, 480, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (2, 'China', 'China', 'CN', 'asia', 'Médio', 'Mandarim', 'Ritmo acelerado, tecnologia e milênios de história.', 'Crescimento rápido de programas de intercâmbio em Xangai e Pequim.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Flag_of_the_People%27s_Republic_of_China.svg/960px-Flag_of_the_People%27s_Republic_of_China.svg.png', 816, 792, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (3, 'Alemanha', 'Germany', 'DE', 'europa', 'Médio', 'Alemão', 'Precisão, engenharia e universidades públicas de peso.', 'Berlim e Munique concentram forte oferta de programas técnicos.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Flag_of_Germany.svg/960px-Flag_of_Germany.svg.png', 854, 703, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (4, 'Estados Unidos', 'United States of America', 'US', 'america_norte', 'Alto', 'Inglês', 'Diversidade cultural e vida de campus intensa.', 'Nova York e Boston lideram a procura por Study & Work.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Flag_of_the_United_States_%28DDD-F-416E_specifications%29.svg/960px-Flag_of_the_United_States_%28DDD-F-416E_specifications%29.svg.png', 723, 641, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (5, 'Canadá', 'Canada', 'CA', 'america_norte', 'Médio', 'Inglês e Francês', 'Acolhedor, multicultural e com natureza próxima das cidades.', 'Toronto e Vancouver com boas regras de trabalho pra estudantes.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Flag_of_Canada_%28Pantone%29.svg/960px-Flag_of_Canada_%28Pantone%29.svg.png', 756, 378, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (6, 'Austrália', 'Australia', 'AU', 'oceania', 'Alto', 'Inglês', 'Ar livre, praia e um jeito mais informal de viver.', 'Sydney e Melbourne combinam ensino de qualidade com qualidade de vida.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Flag_of_Australia_%28converted%29.svg/960px-Flag_of_Australia_%28converted%29.svg.png', 377, 240, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (7, 'Nova Zelândia', 'New Zealand', 'NZ', 'oceania', 'Alto', 'Inglês', 'Natureza preservada e comunidades pequenas e receptivas.', 'Auckland e Wellington, ótimas para quem busca tranquilidade.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Flag_of_New_Zealand.svg/960px-Flag_of_New_Zealand.svg.png', 322, 210, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (8, 'Irlanda', 'Ireland', 'IE', 'europa', 'Médio', 'Inglês', 'Hospitalidade, música ao vivo e história viva nos pubs e ruas.', 'Dublin e Cork com boa relação custo-benefício pra cursos de idioma.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Flag_of_Ireland.svg/960px-Flag_of_Ireland.svg.png', 224, 130, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (9, 'Portugal', 'Portugal', 'PT', 'europa', 'Médio', 'Português', 'Fado, gastronomia à base de bacalhau e frutos do mar, e uma rotina bem mais tranquila que a de outras capitais europeias.', 'Destino cada vez mais procurado por brasileiros pela língua compartilhada, custo de vida menor que o resto da Europa Ocidental e facilidade de cidadania.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Flag_of_Portugal_%28official%29.svg/960px-Flag_of_Portugal_%28official%29.svg.png', 512, 240, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (10, 'Espanha', 'Spain', 'ES', 'europa', 'Médio', 'Espanhol', 'Flamenco, gastronomia regional (tapas, paella) e uma vida noturna que começa tarde e vai até o amanhecer.', 'Um dos destinos mais procurados do mundo pra aprender espanhol, com forte tradição universitária e vida cultural intensa.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Flag_of_Spain.svg/960px-Flag_of_Spain.svg.png', 631, 310, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (11, 'França', 'France', 'FR', 'europa', 'Alto', 'Francês', 'Arte, gastronomia refinada e uma vida cultural com museus e centros de moda entre os mais influentes do mundo.', 'Berço do ensino formal de idiomas (Alliance Française) e de uma das tradições acadêmicas mais respeitadas da Europa.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Flag_of_France.svg/960px-Flag_of_France.svg.png', 498, 289, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (12, 'Itália', 'Italy', 'IT', 'europa', 'Médio', 'Italiano', 'Arte renascentista, culinária regional e uma relação com comida e família que atravessa qualquer conversa.', 'História e patrimônio artístico em cada esquina, com cursos de idioma e gastronomia muito procurados por quem já fala português.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Flag_of_Italy.svg/960px-Flag_of_Italy.svg.png', 407, 198, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (13, 'Holanda', 'Netherlands', 'NL', 'europa', 'Alto', 'Holandês', 'Bicicletas em vez de carro, mentalidade aberta e uma vida ao ar livre mesmo com o clima nem sempre favorável.', 'Universidades bem ranqueadas com cursos inteiros em inglês, o que facilita muito a vida de quem ainda não fala holandês.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Flag_of_the_Netherlands.svg/960px-Flag_of_the_Netherlands.svg.png', 289, 176, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (14, 'Malta', 'Malta', 'MT', 'europa', 'Médio', 'Inglês e maltês', 'Ilha pequena, história marcada por fenícios, romanos e cavaleiros, e praias a poucos minutos de qualquer escola.', 'Um dos destinos mais em conta da Europa pra estudar inglês, com clima mediterrâneo o ano todo.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Flag_of_Malta.svg/960px-Flag_of_Malta.svg.png', 214, 42, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (15, 'Japão', 'Japan', 'JP', 'asia', 'Alto', 'Japonês', 'Etiqueta bem definida, pontualidade quase religiosa e uma culinária que vai muito além do que chega no Brasil.', 'Tecnologia de ponta ao lado de tradições milenares, com forte apelo pra quem se interessa por cultura pop japonesa.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Flag_of_Japan.svg/960px-Flag_of_Japan.svg.png', 356, 287, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (16, 'Coreia do Sul', 'South Korea', 'KR', 'asia', 'Médio', 'Coreano', 'K-pop, k-dramas e uma gastronomia picante que já conquistou fãs no mundo todo.', 'Popularidade crescente puxada pela cultura pop coreana, com universidades fortes em tecnologia e design.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Flag_of_South_Korea.svg/960px-Flag_of_South_Korea.svg.png', 298, 191, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (17, 'Singapura', 'Singapore', 'SG', 'asia', 'Alto', 'Inglês', 'Mistura de tradições chinesa, malaia e indiana, cidade extremamente organizada e gastronomia de rua premiada.', 'Hub educacional multicultural da Ásia, com ensino em inglês e universidades tecnológicas de referência.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Flag_of_Singapore.svg/960px-Flag_of_Singapore.svg.png', 187, 34, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (18, 'México', 'Mexico', 'MX', 'america_norte', 'Baixo', 'Espanhol', 'Herança pré-colombiana viva no dia a dia, gastronomia riquíssima e festividades que tomam as ruas o ano inteiro.', 'Proximidade cultural com o Brasil e custo baixo tornam o país uma porta de entrada popular pra cursos intensivos de espanhol.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Flag_of_Mexico.svg/960px-Flag_of_Mexico.svg.png', 276, 165, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (19, 'Argentina', 'Argentina', 'AR', 'america_sul', 'Baixo', 'Espanhol', 'Tango, futebol como religião e uma cultura de café e conversa que lembra bastante o Brasil.', 'Vizinho de fronteira com universidades tradicionais e custo de vida baixo pra quem já entende um pouco de espanhol.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Flag_of_Argentina.svg/960px-Flag_of_Argentina.svg.png', 341, 128, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (20, 'Chile', 'Chile', 'CL', 'america_sul', 'Médio', 'Espanhol', 'Vinhos reconhecidos internacionalmente, forte cena musical e uma geografia que muda completamente a cada poucas horas de viagem.', 'Estabilidade econômica na região, com paisagens que vão do deserto do Atacama à Patagônia.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Flag_of_Chile.svg/960px-Flag_of_Chile.svg.png', 198, 94, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (21, 'Colômbia', 'Colombia', 'CO', 'america_sul', 'Baixo', 'Espanhol', 'Música (salsa, cumbia), café de qualidade internacional e uma biodiversidade entre as maiores do planeta.', 'Popularidade crescente pra intercâmbio de espanhol, com custo acessível e cidades cada vez mais procuradas por estrangeiros.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Flag_of_Colombia.svg/960px-Flag_of_Colombia.svg.png', 176, 88, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (22, 'África do Sul', 'South Africa', 'ZA', 'africa', 'Baixo', 'Inglês', 'País com 11 línguas oficiais, forte diversidade étnica e uma história recente marcada pelo fim do apartheid.', 'Ensino em inglês com custo de vida baixo e uma natureza exuberante, cada vez mais procurada por quem quer fugir do óbvio.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/af/Flag_of_South_Africa.svg/960px-Flag_of_South_Africa.svg.png', 143, 71, true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.paises (id, nome, nome_ingles, codigo_iso, regiao, custo_de_vida, idioma, cultura, descricao, imagem_url, intercambistas, universidades, ativo) VALUES (23, 'Marrocos', 'Morocco', 'MA', 'africa', 'Baixo', 'Árabe e francês', 'Souks, arquitetura mourisca e uma gastronomia de especiarias que marca qualquer visitante.', 'Mistura de culturas árabe, berbere e francesa bem na porta de entrada do continente africano com a Europa.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Flag_of_Morocco.svg/960px-Flag_of_Morocco.svg.png', 96, 53, true) ON CONFLICT (id) DO NOTHING;
