BEGIN;
SELECT setval(pg_get_serial_sequence('public.tags', 'id'), COALESCE((SELECT MAX(id) FROM public.tags), 1), true);
SELECT setval(pg_get_serial_sequence('public.paises', 'id'), COALESCE((SELECT MAX(id) FROM public.paises), 1), true);
SELECT setval(pg_get_serial_sequence('public.estados', 'id'), COALESCE((SELECT MAX(id) FROM public.estados), 1), true);
SELECT setval(pg_get_serial_sequence('public.programas', 'id'), COALESCE((SELECT MAX(id) FROM public.programas), 1), true);
SELECT setval(pg_get_serial_sequence('public.agencias', 'id'), COALESCE((SELECT MAX(id) FROM public.agencias), 1), true);
SELECT setval(pg_get_serial_sequence('public.planos', 'id'), COALESCE((SELECT MAX(id) FROM public.planos), 1), true);
SELECT setval(pg_get_serial_sequence('public.avaliacoes', 'id'), COALESCE((SELECT MAX(id) FROM public.avaliacoes), 1), true);
COMMIT;